@import "tailwindcss";
@import "tw-animate-css";
@import "@fontsource-variable/geist";

@custom-variant dark (&:is(.dark *));

@theme {
  --color-brand-50: #fde8eb;
  --color-brand-100: #f9c5cd;
  --color-brand-200: #f48e9f;
  --color-brand-300: #ef5771;
  --color-brand-400: #e94560;
  --color-brand-500: #d91a3a;
  --color-brand-600: #b0152e;
  --color-brand-700: #871022;
  --color-brand-800: #5e0b17;
  --color-brand-900: #35060c;
  --color-brand: #e94560;

  --color-cyan-50: #ccfaff;
  --color-cyan-100: #99f5ff;
  --color-cyan-200: #4deeff;
  --color-cyan-300: #00e5ff;
  --color-cyan-400: #00d9ff;
  --color-cyan-500: #00b8d9;
  --color-cyan-600: #0097b3;
  --color-cyan-700: #00758c;
  --color-cyan-800: #005466;
  --color-cyan-900: #003240;
  --color-cyan: #00d9ff;

  --font-sans: "Geist Variable", sans-serif;
  --font-display: "Geist Variable", sans-serif;
}

@keyframes fadeInUp { from { opacity: 0; transform: translateY(30px); } to { opacity: 1; transform: translateY(0); } }
@keyframes float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-10px); } }
@keyframes kenburns { 0% { transform: scale(1); } 100% { transform: scale(1.1); } }
@keyframes mobileNavIn { from { opacity: 0; transform: translateY(-8px); } to { opacity: 1; transform: translateY(0); } }
@keyframes mobileNavBackdrop { from { opacity: 0; } to { opacity: 1; } }
@keyframes pulse-soft { 0%, 100% { opacity: 0.6; } 50% { opacity: 1; } }
@keyframes modalIn { from { opacity: 0; transform: scale(0.95) translateY(10px); } to { opacity: 1; transform: scale(1) translateY(0); } }
@keyframes modalBackdrop { from { opacity: 0; } to { opacity: 1; } }
@keyframes certSlideIn { from { transform: translateY(40px) scale(0.95); opacity: 0; } to { transform: translateY(0) scale(1); opacity: 1; } }
@keyframes certBackdropIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes blink { 50% { opacity: 0; } }

:root, [data-theme="dark"] {
  --hover-subtle: rgba(255,255,255,0.05);
  --bg-primary: #0a0a0a;
  --bg-secondary: #111;
  --bg-card: #0d0d1a;
  --bg-surface: #0d0d0d;
  --nav-bg: rgba(10,10,10,0.7);
  --text-primary: #eaeaea;
  --text-secondary: #ccc;
  --text-tertiary: #aaa;
  --text-muted: #888;
  --text-subtle: #555;
  --text-faint: #666;
  --border-color: #222;
  --border-light: #333;
  --badge-bg: #222;
  --nav-border: rgba(255,255,255,0.05);
  --modal-bg: #111;
  --modal-border: #333;
  --section-glow-1: #0f0a1a;
  --section-glow-2: #0a0a1a;
  --section-glow-3: #0f0a0a;
}

[data-theme="light"] {
  --hover-subtle: rgba(0,0,0,0.05);
  --bg-primary: #ffffff;
  --bg-secondary: #f5f5f5;
  --bg-card: #f0f0fa;
  --bg-surface: #fafafa;
  --nav-bg: rgba(255,255,255,0.8);
  --text-primary: #1a1a1a;
  --text-secondary: #333;
  --text-tertiary: #555;
  --text-muted: #777;
  --text-subtle: #999;
  --text-faint: #aaa;
  --border-color: #e0e0e0;
  --border-light: #ddd;
  --badge-bg: #eee;
  --nav-border: rgba(0,0,0,0.08);
  --modal-bg: #f5f5f5;
  --modal-border: #ddd;
  --section-glow-1: #f5edff;
  --section-glow-2: #edf3ff;
  --section-glow-3: #fff0ed;
}

body {
  background: var(--bg-primary);
  color: var(--text-primary);
  font-family: "Geist Variable", sans-serif;
  transition: background 0.3s ease, color 0.3s ease;
}

::selection { background: #e94560; color: #fff; }
html { scroll-behavior: smooth; }

/* Utility classes */
.bg-primary { background: var(--bg-primary); }
.bg-secondary { background: var(--bg-secondary); }
.hover-subtle:hover { background: var(--hover-subtle); }
.bg-card { background: var(--bg-card); }
.bg-surface { background: var(--bg-surface); }
.bg-badge { background: var(--badge-bg); }
.nav-bg { background: var(--nav-bg); }
.text-primary { color: var(--text-primary); }
.text-secondary { color: var(--text-secondary); }
.text-tertiary { color: var(--text-tertiary); }
.text-muted { color: var(--text-muted); }
.text-subtle { color: var(--text-subtle); }
.text-faint { color: var(--text-faint); }
.border-custom { border-color: var(--border-color); }
.border-light { border-color: var(--border-light); }

.card-bg { background: linear-gradient(135deg, var(--bg-secondary), var(--bg-card)); }
.section-bg-1 { background: linear-gradient(to bottom, var(--bg-primary), var(--section-glow-1), var(--bg-primary)); }
.section-bg-2 { background: linear-gradient(to bottom, var(--bg-primary), var(--section-glow-2), var(--bg-primary)); }
.section-bg-3 { background: linear-gradient(to bottom, var(--bg-primary), var(--section-glow-3), var(--bg-primary)); }

.gradient-text {
  background: linear-gradient(135deg, #e94560, #00d9ff);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text;
}

.glow { box-shadow: 0 0 30px rgba(233, 69, 96, 0.3); }
.glow-cyan { box-shadow: 0 0 30px rgba(0, 217, 255, 0.2); }
.hover-glow:hover { box-shadow: 0 0 25px rgba(233, 69, 96, 0.5); transform: translateY(-2px); }
.nav-blur { backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px); }

/* Badge */
.badge {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 4px 12px; border-radius: 9999px;
  font-size: 11px; font-weight: 600; letter-spacing: 0.02em;
}

/* Timeline */
.timeline-dot {
  width: 14px; height: 14px; border-radius: 50%;
  border: 3px solid #e94560; background: var(--bg-primary);
  flex-shrink: 0; position: relative; z-index: 1;
}
.timeline-line {
  position: absolute; top: 20px; left: 6px;
  width: 2px; height: calc(100% + 24px);
  background: linear-gradient(to bottom, #e94560, #00d9ff);
}
.exp-card { transition: all 0.3s ease; }
.exp-card:hover { transform: translateX(8px); }

/* Project card */
.project-card { transition: all 0.3s ease; border: 1px solid transparent; }
.project-card:hover { border-color: #e94560; transform: translateY(-8px); box-shadow: 0 20px 40px rgba(0,0,0,0.4); }

/* Tech icon */
.icon-tech { width: 40px; height: 40px; transition: all 0.3s ease; opacity: 0.8; }
.icon-tech:hover { opacity: 1; transform: scale(1.2) rotate(5deg); }

/* Tech popup */
.tech-popup {
  position: fixed; z-index: 100;
  padding: 0.75rem 1rem; border-radius: 0.75rem;
  background: var(--bg-secondary); border: 1px solid var(--border-light);
  font-size: 0.8rem; color: var(--text-tertiary); line-height: 1.5;
  max-width: 300px; pointer-events: none;
  opacity: 0; transition: all 0.25s ease;
  transform: translateY(8px);
  box-shadow: 0 10px 40px rgba(0,0,0,0.5);
}
.tech-popup.show { opacity: 1; transform: translateY(0); }
.tech-popup .tp-label { color: #00d9ff; font-weight: 600; }

/* Slideshow */
.bg-slideshow { position: absolute; inset: 0; z-index: 0; overflow: hidden; cursor: grab; user-select: none; }
.bg-slideshow:active { cursor: grabbing; }
.bg-slide {
  position: absolute; inset: 0;
  background-size: cover; background-position: center;
  opacity: 0; transition: opacity 1.5s ease;
  pointer-events: none;
}
.bg-slide.active { opacity: 1; }
.bg-slide.kenburns { animation: kenburns 10s ease forwards; }

.slide-nav {
  position: absolute; top: 50%; z-index: 5; transform: translateY(-50%);
  width: 48px; height: 48px; border-radius: 50%;
  background: rgba(0,0,0,0.4); border: 1px solid rgba(255,255,255,0.1);
  color: #888; cursor: pointer; display: flex; align-items: center; justify-content: center;
  transition: all 0.3s ease; backdrop-filter: blur(4px);
}
.slide-nav:hover { background: rgba(233,69,96,0.3); color: #fff; border-color: #e94560; }
.slide-nav.prev { left: 16px; }
.slide-nav.next { right: 16px; }
@media (max-width: 640px) { .slide-nav { display: none; } }

/* Section reveal */
.section-in {
  opacity: 0; transform: translateY(40px);
  transition: opacity 0.8s ease, transform 0.8s ease;
}
.section-in.visible { opacity: 1; transform: translateY(0); }

.stagger-child {
  opacity: 0; transform: translateY(30px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}
.section-in.visible .stagger-child { opacity: 1; transform: translateY(0); }
.section-in.visible .stagger-child:nth-child(1) { transition-delay: 0s; }
.section-in.visible .stagger-child:nth-child(2) { transition-delay: 0.1s; }
.section-in.visible .stagger-child:nth-child(3) { transition-delay: 0.2s; }
.section-in.visible .stagger-child:nth-child(4) { transition-delay: 0.3s; }
.section-in.visible .stagger-child:nth-child(5) { transition-delay: 0.4s; }
.section-in.visible .stagger-child:nth-child(6) { transition-delay: 0.5s; }
.section-in.visible .stagger-child:nth-child(7) { transition-delay: 0.6s; }
.section-in.visible .stagger-child:nth-child(8) { transition-delay: 0.7s; }

/* Animations */
.animate-fade-in-up { animation: fadeInUp 0.8s ease forwards; }
.animate-float { animation: float 4s ease-in-out infinite; }
.animate-kenburns { animation: kenburns 10s ease forwards; }
.animate-pulse-soft { animation: pulse-soft 2s ease-in-out infinite; }
.animate-delay-1 { animation-delay: 0.2s; }
.animate-delay-2 { animation-delay: 0.4s; }
.animate-delay-3 { animation-delay: 0.6s; }
.animate-delay-4 { animation-delay: 0.8s; }

/* Mobile nav */
#mobile-nav-menu.open { display: block; animation: mobileNavIn 0.2s ease forwards; }
#mobile-nav-backdrop.open { display: block; animation: mobileNavBackdrop 0.2s ease forwards; }
#mobile-nav-toggle.open span:nth-child(1) { transform: translateY(6px) rotate(45deg); }
#mobile-nav-toggle.open span:nth-child(2) { opacity: 0; }
#mobile-nav-toggle.open span:nth-child(3) { transform: translateY(-6px) rotate(-45deg); }

/* Modal */
.modal-overlay { display: none; position: fixed; inset: 0; z-index: 999; align-items: center; justify-content: center; padding: 1rem; }
.modal-overlay.active { display: flex; }
.modal-backdrop { position: absolute; inset: 0; background: rgba(0,0,0,0.7); backdrop-filter: blur(4px); }
.modal-container { position: relative; background: var(--modal-bg); border: 1px solid var(--modal-border); border-radius: 1rem; max-width: 42rem; width: 100%; max-height: 90vh; overflow-y: auto; padding: 1.5rem; }
.modal-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 1rem; }
.modal-close { width: 2rem; height: 2rem; border-radius: 9999px; border: none; background: var(--badge-bg); color: var(--text-muted); font-size: 1.25rem; cursor: pointer; display: flex; align-items: center; justify-content: center; transition: all 0.2s; }
.modal-close:hover { background: #e94560; color: #fff; }
.modal-image { width: 100%; border-radius: 0.75rem; background: linear-gradient(135deg, var(--bg-card), var(--modal-bg)); min-height: 200px; display: flex; align-items: center; justify-content: center; color: var(--text-subtle); font-size: 0.875rem; }
.modal-footer { display: flex; gap: 0.75rem; margin-top: 1.5rem; flex-wrap: wrap; }
.modal-overlay.active .modal-container { animation: modalIn 0.25s ease forwards; }
.modal-overlay.active .modal-backdrop { animation: modalBackdrop 0.25s ease forwards; }

/* Cert overlay */
.cert-overlay { display: none; position: fixed; inset: 0; z-index: 1000; align-items: center; justify-content: center; }
.cert-overlay.active { display: flex; }
.cert-backdrop { position: absolute; inset: 0; background: rgba(0,0,0,0.85); backdrop-filter: blur(8px); }
.cert-overlay.active .cert-backdrop { animation: certBackdropIn 0.3s ease forwards; }
.cert-content { position: relative; width: 100%; max-width: 520px; max-height: 90vh; overflow-y: auto; z-index: 10; background: var(--modal-bg); border: 1px solid var(--modal-border); border-radius: 1.25rem; padding: 1.5rem; transform: translateY(30px) scale(0.95); opacity: 0; }
.cert-overlay.active .cert-content { animation: certSlideIn 0.35s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
.cert-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 1.5rem; }
.cert-close { width: 2rem; height: 2rem; border-radius: 9999px; border: none; background: var(--badge-bg); color: var(--text-muted); font-size: 1.25rem; cursor: pointer; display: flex; align-items: center; justify-content: center; transition: all 0.2s; }
.cert-close:hover { background: #e94560; color: #fff; transform: rotate(90deg); }
.cert-body { text-align: left; }
.cert-card { background: var(--bg-card); border: 1px solid var(--border-light); border-radius: 0.75rem; padding: 1rem; transition: all 0.2s; }
.cert-card:hover { border-color: #00d9ff40; }
.cert-bar-track { height: 4px; background: var(--badge-bg); border-radius: 2px; overflow: hidden; }
.cert-bar-fill { height: 100%; background: linear-gradient(90deg, #00d9ff, #e94560); border-radius: 2px; transition: width 0.5s ease; }

/* Service cards — abstract animated */
@keyframes orbFloat { 0%, 100% { transform: translateY(0) scale(1); } 50% { transform: translateY(-6px) scale(1.08); } }
@keyframes orbPulse { 0%, 100% { box-shadow: 0 0 20px rgba(233,69,96,0.15); } 50% { box-shadow: 0 0 40px rgba(233,69,96,0.35); } }
@keyframes orbPulseCyan { 0%, 100% { box-shadow: 0 0 20px rgba(0,217,255,0.15); } 50% { box-shadow: 0 0 40px rgba(0,217,255,0.35); } }
@keyframes particleDrift {
  0% { opacity: 0; transform: translate(0, 0) scale(0); }
  30% { opacity: 0.6; }
  100% { opacity: 0; transform: translate(var(--dx, 30px), var(--dy, -40px)) scale(1); }
}

.service-card {
  position: relative; overflow: hidden;
  background: var(--bg-secondary); border: 1px solid var(--border-color);
  border-radius: 1rem; padding: 1.25rem;
  transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
}
.service-card::before {
  content: ''; position: absolute; inset: 0; z-index: 0;
  background: radial-gradient(circle at 30% 20%, rgba(233,69,96,0.04), transparent 60%),
              radial-gradient(circle at 70% 80%, rgba(0,217,255,0.03), transparent 60%);
  opacity: 0; transition: opacity 0.4s ease;
}
.service-card:hover { border-color: rgba(233,69,96,0.3); transform: translateY(-6px) scale(1.02); }
.service-card:hover::before { opacity: 1; }
.service-card:hover .service-orb { animation: orbFloat 2s ease-in-out infinite; }
.service-card:hover .service-orb--brand { animation: orbFloat 2s ease-in-out infinite, orbPulse 2s ease-in-out infinite; }
.service-card:hover .service-orb--cyan { animation: orbFloat 2s ease-in-out infinite, orbPulseCyan 2s ease-in-out infinite; }
.service-card:hover .service-particles::before,
.service-card:hover .service-particles::after { animation: particleDrift 1.5s ease-out infinite; }
.service-card:hover .service-particles::after { animation-delay: 0.3s; --dx: -25px; --dy: -35px; }

.service-orb {
  width: 2.5rem; height: 2.5rem; border-radius: 0.75rem;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 0.75rem; position: relative; z-index: 10;
  transition: all 0.3s ease;
}
.service-orb--brand { background: rgba(233,69,96,0.1); color: #e94560; }
.service-orb--cyan { background: rgba(0,217,255,0.1); color: #00d9ff; }

.service-particles { position: absolute; top: 1rem; left: 1rem; width: 2.5rem; height: 2.5rem; pointer-events: none; }
.service-particles::before, .service-particles::after {
  content: ''; position: absolute; width: 4px; height: 4px; border-radius: 50%;
  background: rgba(233,69,96,0.5); top: 50%; left: 50%; opacity: 0;
}

/* Badge tech (colorful) */
.badge-tech {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 4px 10px; border-radius: 9999px;
  font-size: 11px; font-weight: 600; letter-spacing: 0.02em;
  transition: all 0.25s ease; cursor: default;
  text-shadow: 0 0 8px var(--badge-glow, transparent);
}
.badge-tech:hover {
  transform: scale(1.08) translateY(-1px);
  box-shadow: 0 2px 12px var(--badge-glow, rgba(0,0,0,0.2));
  filter: brightness(1.15);
}

/* Dotted background pattern (Figma-like) */
.bg-dots {
  background-image: radial-gradient(circle, var(--text-muted) 1px, transparent 1px);
  background-size: 20px 20px;
  opacity: 0.15;
  pointer-events: none;
}

/* Scroll progress dots */
.scroll-dots {
  position: fixed; right: 1.25rem; top: 50%; transform: translateY(-50%);
  z-index: 90; display: flex; flex-direction: column; gap: 0.75rem;
  align-items: center;
}
.scroll-dot {
  position: relative; width: 10px; height: 10px; border-radius: 50%;
  background: var(--text-subtle); opacity: 0.4;
  transition: all 0.3s ease; cursor: pointer; display: block;
}
.scroll-dot:hover { opacity: 0.8; transform: scale(1.3); }
.scroll-dot.active {
  opacity: 1; background: #e94560; transform: scale(1.4);
  box-shadow: 0 0 12px rgba(233,69,96,0.5);
}
.scroll-dot-tooltip {
  position: absolute; right: 22px; top: 50%; transform: translateY(-50%);
  background: var(--bg-secondary); border: 1px solid var(--border-light);
  color: var(--text-primary); font-size: 0.7rem; font-weight: 600;
  padding: 4px 10px; border-radius: 6px; white-space: nowrap;
