  --text-secondary: #333;
  --text-tertiary: #555;
  --text-muted: #777;
  --text-subtle: #999;
  --text-faint: #aaa;
  --border-color: #e0e0e0;
  --border-light: #ddd;
  --badge-bg: #eee;
  --nav-border: rgba(0,0,0,0.08);
  --modal-bg: #f5f5f5;
